 lb(){const w=lbs(),o=pick([2,2.5,4,5]),d=pick(DRUGS),g=w/LB*o,b=w*o;if(tied(g,b))return null;return{video:'weight',order:`${d} is ordered at <b>${f(o,3)} mg/kg</b> for a <b>${w} lb</b> patient. Find the dose in mg.`,good:res(line(`${w} lb`,fr('1 kg','2.2046 lb'),fr(`${f(o,3)} mg`,'1 kg')),`${f(g,3)} mg`),bad:res(line(`${w} lb`,fr(`${f(o,3)} mg`,'1 kg')),`${f(b,3)} mg`),gv:g,bv:b,err:'Skipped the lb to kg step',errNo:'The work includes 1 kg / 2.2046 lb, so the weight is in kg before the mg/kg factor.',fix:'Pounds cannot cancel with kg, so the weight must be converted first.',decoys:[['The mg/kg factor is upside down','The factor has mg on top and kg on the bottom, which leads to an answer in mg.'],['It needs to be divided by doses per day','The order gives one dose in mg/kg and has no daily total to divide.']]}},
 lbx(){const k=rnd(45,105),w=+(k*LB).toFixed(0),o=pick([2,4,5]),g=w/LB*o,b=w*LB*o;if(tied(g,b))return null;return{video:'weight',order:`A patient weighs <b>${w} lb</b>. The order is <b>${f(o,3)} mg/kg</b>. Find the dose in mg.`,good:res(line(`${w} lb`,fr('1 kg','2.2046 lb'),fr(`${f(o,3)} mg`,'1 kg')),`${f(g,3)} mg`),bad:res(line(`${w} lb`,fr('2.2046 lb','1 kg'),fr(`${f(o,3)} mg`,'1 kg')),`${f(b,3)} mg`),gv:g,bv:b,err:'The lb to kg factor is upside down',errNo:'The factor has lb on the bottom, so lb cancels correctly.',fix:'The old unit, lb, belongs on the bottom. A weight in kg is a smaller number than the same weight in lb.',decoys:[['The order should use grams','The order and the answer both use mg, so no gram step is needed.'],['It needs a mL factor','The question asks for mg, so the setup ends at mg.']]}},
 label(){const l=pick(LABELS),c=l[0]/l[1],v=pick([.5,1,1.5,2,2.5,3,4]),mg=c*v,b=mg*c;if(tied(mg,b,v))return null;return{video:'routine',order:`Order: <b>${f(mg,3)} mg</b>. The vial is <b>${f(c,3)} mg/mL</b>. Find the volume.`,good:res(line(`${f(mg,3)} mg`,fr('1 mL',`${f(c,3)} mg`)),`${f(v,3)} mL`),bad:res(line(`${f(mg,3)} mg`,fr(`${f(c,3)} mg`,'1 mL')),`${f(b,3)} mL`),gv:v,bv:b,err:'The vial strength is upside down',errNo:'The strength has mg on the bottom, so mg cancels and mL remains.',fix:'To cancel mg, the vial strength must be written as 1 mL over its mg.',decoys:[['It needs the patient weight','The order is already a fixed mg amount, so weight is not part of this setup.'],['It needs a time factor','This asks for one volume, so no time unit is involved.']]}},
 gram(){const l=pick([[50,1],[100,1],[125,1],[250,1]]),c=l[0],v=pick([1,2,3,4]),g=c*v/1000,b=g/c;if(tied(g,v)||b<.001)return null;return{video:'routine',order:`Order: <b>${f(g,3)} g</b>. The vial is <b>${f(c,3)} mg/mL</b>. Find the volume.`,good:res(line(`${f(g,3)} g`,fr('1000 mg','1 g'),fr('1 mL',`${f(c,3)} mg`)),`${f(v,3)} mL`),bad:res(line(`${f(g,3)} g`,fr('1 mL',`${f(c,3)} mg`)),`${f(b,3)} mL`),gv:v,bv:b,err:'Skipped the g to mg step',errNo:'The work includes 1000 mg / 1 g, so the order and the vial use the same unit.',fix:'Grams do not cancel with mg. Convert the order to mg first.',decoys:[['The vial strength is flipped','The strength has mg on the bottom, which is the side needed to cancel mg.'],['It needs lb to kg','The order is a fixed amount and does not depend on weight.']]}},
 day(){const k=rnd(120,420)/10,o=pick([15,20,30,40]),n=pick([2,3,4]),g=k*o/n,b=k*o;if(tied(g,b))return null;return{video:'weight',order:`Order: <b>${f(o,3)} mg/kg/day</b> in <b>${n} equal doses</b> for a <b>${f(k,3)} kg</b> child. Find the mg per dose.`,good:res(line(`${f(k,3)} kg`,fr(`${f(o,3)} mg`,'1 kg·day'),fr('1 day',`${n} doses`)),`${f(g,3)} mg/dose`),bad:res(line(`${f(k,3)} kg`,fr(`${f(o,3)} mg`,'1 kg·day')),`${f(b,3)} mg/dose`),gv:g,bv:b,err:'Used the daily total as one dose',errNo:`The work includes 1 day / ${n} doses, so the total is split correctly.`,fix:'The mg/kg/day order gives a daily total. It must be divided among the doses.',decoys:[['The weight still needs lb to kg','The weight is already given in kg.'],['The answer needs mL','The question asks for mg per dose, so the setup ends there.']]}},
